#!/usr/bin/env bash
# All four LTLf solvers on small dot instances (k = 5..80, generated by ltl_scaling_study.dot_text):
# 60 s budget (export + solve), 3 repetitions per decided instance; every dot language is nonempty.
cd "$(dirname "$0")/../.."
O=results/ltlf_solvers_dot_small_60s_20260921
INPUTS=$(cut -f3 $O/instances.tsv | sed "s|^|$O/inputs/|")
for s in aalta black lisa lydia; do
  python3 scripts/ltlf_solver_baseline.py $INPUTS --solver $s --timeout 60 --repetitions 3 --witness \
    --reference $O/expected.jsonl --out $O/records_$s.jsonl > $O/log_$s.txt 2>&1
done
